# =============================================================================
# 维表映射配置（由 generate_dimension_map_from_schema.py 根据表结构 V1.2 生成）
# 改完后运行：python3 build_dify_bundle.py → 复制 dify_mes_dimension_node.py 到 Dify
# 手工微调后可重新运行本脚本（会覆盖）；或只改本文件后 build_dify_bundle.py
# =============================================================================
#
# 写法说明：
#   [表 表名]           一张业务主表
#   标签=               中文说明
#   关键词=             用户问题里出现这些词时，选中该表（逗号分隔）
#   别名=               SQL 里事实表别名，如 l、m
#
#   [映射 英文名]       一组「事实字段 → 维表 → 中文列」
#   字段=               事实表上的列，多个用逗号分隔
#   类型=账号           仅人员账号字段填写（开工人、完工人等）
#   类型=枚举           状态/类型等码值字段，SELECT 须用 CASE 译码
#   可选=是             不需要时可不写；写了表示可不生成该组
#   说明=               给维护人看的备注
#   关联=别名 | 维表 | ON条件 [| 依赖=上一别名]
#   列=SQL表达式 | 中文列名
#   展示列=表达式 | 中文列名   （本表非外键列，列表须 AS 中文表头）
#   禁止=               不要这样写 SQL
#
# [全局] 下「禁止=」对所有表生效

[全局]
默认别名=l
禁止=TBL_SFC_WS_LOG 上使用 CCUSTOMER_CODE（须 CUSTOMER_CODE）
禁止=TBL_SFC_WS_LOG 上使用 CSCANNED_BARCODE（须 CSCAN_BARCODE）
禁止=FROM/JOIN 表名与 WITH (NOLOCK) 拆成两行
禁止=用 TBL_EAP_DEVICE 解析 CWC_ID（工作中心/机台须 TBL_BD_WC）
禁止=p.CPROCESS_ID 作工序主键（须 p.CID = 事实表.CPROCESS_ID）
禁止=wc.CWC_NAME AS [工序名称] 或 p.CPROCESS_NAME AS [工作中心名称]
禁止=查采购订单明细时只 FROM TBL_SRM_PO 不 JOIN TBL_SRM_PO_DETAIL
禁止=问句含 PO/POA 采购单号却不写 WHERE srmpo.CPO（须 JOIN TBL_SRM_PO）
禁止=无时间条件的明细列表查询省略 ORDER BY（须按主时间列 DESC 由近到远）

[表 TBL_SFC_WS_LOG]
标签=生产记录表
关键词=生产记录, 报工, 工位, WS_LOG, 开工, 完工, 是否已审核, 是否完工, 是否已过数
别名=l

[映射 is_check]
字段=CIS_CHECK
类型=枚举
说明=Y/N译码（Y=是，N=否）：是否已审核
列=CASE UPPER(RTRIM(l.CIS_CHECK)) WHEN 'Y' THEN N'是' WHEN 'N' THEN N'否' ELSE l.CIS_CHECK END | 是否已审核
禁止=l.CIS_CHECK AS [是否已审核]

[映射 is_finish]
字段=CIS_FINISH
类型=枚举
说明=Y/N译码（Y=是，N=否）：是否完工
列=CASE UPPER(RTRIM(l.CIS_FINISH)) WHEN 'Y' THEN N'是' WHEN 'N' THEN N'否' ELSE l.CIS_FINISH END | 是否完工
禁止=l.CIS_FINISH AS [是否完工]

[映射 is_wip]
字段=CIS_WIP
类型=枚举
说明=Y/N译码（Y=是，N=否）：是否已过数
列=CASE UPPER(RTRIM(l.CIS_WIP)) WHEN 'Y' THEN N'是' WHEN 'N' THEN N'否' ELSE l.CIS_WIP END | 是否已过数
禁止=l.CIS_WIP AS [是否已过数]

[映射 status]
字段=CSTATUS
类型=枚举
说明=枚举译码（TBL_SFC_WS_LOG 专用）：0待审核、1已通过、2已驳回
列=CASE l.CSTATUS WHEN 0 THEN N'待审核' WHEN 1 THEN N'已通过' WHEN 2 THEN N'已驳回' ELSE CAST(l.CSTATUS AS NVARCHAR(20)) END | 状态
禁止=l.CSTATUS AS [状态]

[映射 work_type]
字段=CWORK_TYPE
类型=枚举
说明=枚举译码：1:正常生产记录(检验生产记录);2:批量生产记录;3:无工单生产记录;4:历史记录新增;5:FQC生产记录
列=CASE l.CWORK_TYPE WHEN 1 THEN N'正常生产记录(检验生产记录)' WHEN 2 THEN N'批量生产记录' WHEN 3 THEN N'无工单生产记录' WHEN 4 THEN N'历史记录新增' WHEN 5 THEN N'FQC生产记录' ELSE CAST(l.CWORK_TYPE AS NVARCHAR(20)) END | 工作类型
禁止=l.CWORK_TYPE AS [工作类型]

[映射 check_user]
字段=CCHECK_USER_NAME
类型=账号
可选=是
关联=u_c | TBL_SYS_USER | u_c.CUSER_NAME = l.CCHECK_USER_NAME
列=l.CCHECK_USER_NAME | 审核人账号
列=u_c.CDISPLAY_NAME | 审核人姓名

[映射 end_user]
字段=CEND_USER_NAME
类型=账号
关联=u_e | TBL_SYS_USER | u_e.CUSER_NAME = l.CEND_USER_NAME
列=l.CEND_USER_NAME | 完工人账号
列=u_e.CDISPLAY_NAME | 完工人姓名

[映射 item]
字段=CITEM_ID
关联=i | TBL_BD_ITEM | i.CID = l.CITEM_ID
列=i.CITEM_NO | 料号
列=i.CITEM_NAME | 品名
列=CASE UPPER(RTRIM(i.CTYPE)) WHEN 'MERGER' THEN N'合拼' WHEN 'SAMPLE' THEN N'样本' WHEN 'BATCH' THEN N'批量生产' ELSE i.CTYPE END | 类型

[映射 mo_lot]
字段=CMO_LOT
关联=mo | TBL_MO | mo.CMO_LOT = l.CMO_LOT
列=mo.CORDER_NO | 工单编号
列=mo.CMO_LOT | 工单批次
列=CASE mo.CSTATUS WHEN 2 THEN N'已发放' WHEN 5 THEN N'已取消' WHEN 6 THEN N'已暂停' WHEN 7 THEN N'外协' ELSE CAST(mo.CSTATUS AS NVARCHAR(20)) END | 工单状态

[映射 process]
字段=CPROCESS_ID
关联=p | TBL_BD_PROCESS | p.CID = l.CPROCESS_ID
列=p.CPROCESS_NAME | 工序名称
列=p.CPROCESS_NO | 工序编码

[映射 scan_barcode_to_mo]
字段=CSCAN_BARCODE
关联=mo2 | TBL_MO | mo2.CMO_LOT = l.CSCAN_BARCODE
列=mo2.CORDER_NO | 工单编号
列=mo2.CMO_LOT | 工单批次
列=CASE mo2.CSTATUS WHEN 2 THEN N'已发放' WHEN 5 THEN N'已取消' WHEN 6 THEN N'已暂停' WHEN 7 THEN N'外协' ELSE CAST(mo2.CSTATUS AS NVARCHAR(20)) END | 工单状态

[映射 start_user]
字段=CSTART_USER_NAME
类型=账号
关联=u_s | TBL_SYS_USER | u_s.CUSER_NAME = l.CSTART_USER_NAME
列=l.CSTART_USER_NAME | 开工人账号
列=u_s.CDISPLAY_NAME | 开工人姓名
禁止=CSTART_USER_NAME AS [开工人姓名] 且无 JOIN TBL_SYS_USER

[映射 template_id_to_np_template]
字段=CTEMPLATE_ID
关联=nptem | TBL_NP_TEMPLATE | nptem.CID = l.CTEMPLATE_ID
列=nptem.CTEMPLATE_NAME | 模板名称

[映射 customer]
字段=CUSTOMER_CODE
关联=cust | TBL_BD_CUSTOMER | cust.CUSTOMER_NO = l.CUSTOMER_CODE
列=cust.CUSTOMER_NAME | 客户名称
列=cust.CUSTOMER_NO | 客户编号

[映射 work_center]
字段=CWC_ID
说明=工作中心两级：父级如开料/钻孔；子级如1#开料机。报工 CWC_ID 多为机台。
关联=wc | TBL_BD_WC | wc.CID = l.CWC_ID
关联=wc_p | TBL_BD_WC | wc_p.CID = wc.CPARENT | 依赖=wc
列=COALESCE(wc_p.CWC_NAME, wc.CWC_NAME) | 工作中心名称
列=COALESCE(wc_p.CWC_NO, wc.CWC_NO) | 工作中心编码
列=wc.CWC_NAME | 机台名称
列=wc.CWC_NO | 机台编码
禁止=用 TBL_EAP_DEVICE 解析 CWC_ID
禁止=p.CPROCESS_NAME AS [工作中心名称]
禁止=仅 wc.CWC_NAME AS [工作中心名称] 且不输出 [机台名称]
禁止=wc.CID = l.CPROCESS_ID 或 p.CID = l.CWC_ID

展示列=l.BOARD_TYPE | 板类型
展示列=l.CCHECK_REMARK | 审核备注
展示列=l.CCHECK_TIME | 审核时间
展示列=l.CEND_TIME | 完工时间
展示列=l.CLEVEL | 等级
展示列=l.CNG_NUMBER | 不良数量
展示列=l.CNUMBER_TYPE | 数量类型
展示列=l.CREMARK | 备注
展示列=l.CSCRAP_NUMBER | 报废数量
展示列=l.CSHIFT | 班次
展示列=l.CSTART_TIME | 开工时间
展示列=l.CUNIT | 单位
展示列=l.CWORK_NUMBER | 工作数量
展示列=l.CID | 主键ID

