[表 TBL_QM_INSPECT_RECORD]
标签=检验记录主表
关键词=检验记录, IPQC, FQC, 品质检验
别名=qir
默认排序=COALESCE(qir.CINSPECT_TIME, qir.CCHECK_TIME, qir.CLAB_INSPECT_TIME) DESC, qir.CID DESC

[映射 decision_mode]
字段=CDECISION_MODE
类型=枚举
说明=判定模式：1系统自动判定、2用户人为判定
列=CASE qir.CDECISION_MODE WHEN 1 THEN N'系统自动判定' WHEN 2 THEN N'用户人为判定' ELSE CAST(qir.CDECISION_MODE AS NVARCHAR(20)) END | 判定模式
禁止=qir.CDECISION_MODE AS [判定模式]

[映射 result]
字段=CRESULT
类型=枚举
说明=检验结果：1合格、2不合格
列=CASE qir.CRESULT WHEN 1 THEN N'合格' WHEN 2 THEN N'不合格' ELSE CAST(qir.CRESULT AS NVARCHAR(20)) END | 检验结果
禁止=qir.CRESULT AS [检验结果]

[映射 status]
字段=CSTATUS
类型=枚举
说明=状态：0待检验、1已检验待审核、2审核通过、3审核驳回
