关键词=放板机状态监控表，两分钟更新一次
别名=eap

[映射 is_board]
字段=CIS_BOARD
类型=枚举
说明=Y/N译码（Y=是，N=否）：是否有板，Y：是；N：否
列=CASE UPPER(RTRIM(eap.CIS_BOARD)) WHEN 'Y' THEN N'是' WHEN 'N' THEN N'否' ELSE eap.CIS_BOARD END | 是否有板
禁止=eap.CIS_BOARD AS [是否有板]

[映射 is_mes_model]
字段=CIS_MES_MODEL
类型=枚举
说明=Y/N译码（Y=是，N=否）：是否MES模式，Y：是；N：否
列=CASE UPPER(RTRIM(eap.CIS_MES_MODEL)) WHEN 'Y' THEN N'是' WHEN 'N' THEN N'否' ELSE eap.CIS_MES_MODEL END | 是否MES模式
禁止=eap.CIS_MES_MODEL AS [是否MES模式]

[映射 is_online]
字段=CIS_ONLINE
类型=枚举
说明=Y/N译码（Y=是，N=否）：是否在线，Y：是；N：否
列=CASE UPPER(RTRIM(eap.CIS_ONLINE)) WHEN 'Y' THEN N'是' WHEN 'N' THEN N'否' ELSE eap.CIS_ONLINE END | 是否在线
禁止=eap.CIS_ONLINE AS [是否在线]

[映射 is_run]
字段=CIS_RUN
类型=枚举
说明=Y/N译码（Y=是，N=否）：是否运行，Y：是；N：否
列=CASE UPPER(RTRIM(eap.CIS_RUN)) WHEN 'Y' THEN N'是' WHEN 'N' THEN N'否' ELSE eap.CIS_RUN END | 是否运行
禁止=eap.CIS_RUN AS [是否运行]

展示列=eap.CDATETIME_MODIFIED | 修改时间
展示列=eap.CPULL_MACHINE_NAME | 放板机名称
展示列=eap.CPULL_MACHINE_NO | 放板机编号（后面加"-放板机"为配置的DEVICE_NAME）

