别名=qal
默认排序=COALESCE(qal.CASSAY_TIME, qal.CSAMPLE_TIME, qal.CRECEIVE_TIME, qal.CTASK_STAND_TIME_S) DESC, qal.CID DESC

[映射 assay_result]
字段=CASSAY_RESULT
类型=枚举
说明=枚举译码：化验结果：1：正常、2：异常
列=CASE qal.CASSAY_RESULT WHEN 1 THEN N'正常' WHEN 2 THEN N'异常' ELSE CAST(qal.CASSAY_RESULT AS NVARCHAR(20)) END | 化验结果
禁止=qal.CASSAY_RESULT AS [化验结果]

[映射 assay_status]
字段=CASSAY_STATUS
类型=枚举
说明=化验流程状态（现场除0/1外常见2~5；5与已审核任务一致，译码为已审核）。勿仅用文档0/1两项
列=CASE qal.CASSAY_STATUS WHEN 0 THEN N'待取样' WHEN 1 THEN N'待接收' WHEN 2 THEN N'待化验' WHEN 3 THEN N'化验中' WHEN 4 THEN N'待审核' WHEN 5 THEN N'已审核' ELSE CAST(qal.CASSAY_STATUS AS NVARCHAR(20)) END | 化验状态
禁止=qal.CASSAY_STATUS AS [化验状态]

[映射 task_type]
字段=CTASK_TYPE
类型=枚举
说明=任务类型：1常规化验、2异常化验（现场CTASK_TYPE取值）
列=CASE qal.CTASK_TYPE WHEN 1 THEN N'常规化验' WHEN 2 THEN N'异常化验' ELSE CAST(qal.CTASK_TYPE AS NVARCHAR(20)) END | 任务类型
禁止=qal.CTASK_TYPE AS [任务类型]
禁止=CAST(qal.CTASK_TYPE AS NVARCHAR(20)) AS [任务类型]

